using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of numbers, structures, and patterns." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Understanding matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Analysis of literature, writing, and rhetoric." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events and their impact on the present." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Email = "achen@university.edu", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 50 papers and holds three patents in fault-tolerant architectures." },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Email = "rmartinez@university.edu", Bio = "Dr. Martinez focuses on artificial intelligence and machine learning, with a particular interest in natural language processing and ethical AI." },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of Mathematics", Email = "sjohnson@university.edu", Bio = "Dr. Johnson is an award-winning educator whose research spans abstract algebra and number theory." },
            new() { Id = 4, Name = "Dr. James Liu", Title = "Associate Professor of Physics", Email = "jliu@university.edu", Bio = "Dr. Liu conducts research in quantum mechanics and particle physics at the university's accelerator lab." },
            new() { Id = 5, Name = "Prof. Emily Davis", Title = "Professor of English", Email = "edavis@university.edu", Bio = "Prof. Davis is a noted literary critic whose work on postmodern American fiction is widely cited." },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor of History", Email = "mbrown@university.edu", Bio = "Dr. Brown specializes in 20th-century European history and the history of international relations." },
            new() { Id = 7, Name = "Dr. Karen Williams", Title = "Professor of Biology", Email = "kwilliams@university.edu", Bio = "Dr. Williams leads the molecular genetics lab and has contributed to breakthroughs in gene therapy research." },
            new() { Id = 8, Name = "Dr. David Park", Title = "Assistant Professor of Mathematics", Email = "dpark@university.edu", Bio = "Dr. Park researches applied statistics and data science, bridging theory with real-world applications." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Emphasis on efficiency analysis using Big-O notation.", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Covers the foundational concepts of AI including search algorithms, knowledge representation, probabilistic reasoning, and an introduction to machine learning. Includes hands-on projects in Python.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Location = "Tech Building 102", DepartmentId = 1, InstructorId = 2, IsFeatured = true },
            new() { Id = 4, Code = "CS 450", Title = "Software Engineering", Description = "Principles of software development including requirements analysis, system design, testing strategies, version control, and agile methodologies. Students work in teams on a semester-long project.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Location = "Tech Building 210", DepartmentId = 1, InstructorId = 2 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential and integral calculus of single-variable functions. Topics include limits, continuity, derivatives, and the Fundamental Theorem of Calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, InstructorId = 3, IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Applications in computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Location = "Math Building 203", DepartmentId = 2, InstructorId = 3 },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and regression analysis. Uses real-world data sets for practical exercises.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", Location = "Math Building 105", DepartmentId = 2, InstructorId = 8 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational motion, and an introduction to oscillations. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Physics Lab 110", DepartmentId = 3, InstructorId = 4 },
            new() { Id = 9, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave-particle duality, the Schrödinger equation, quantum states, and measurement. Prerequisites: PHYS 101, MATH 201.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", Location = "Physics Lab 220", DepartmentId = 3, InstructorId = 4, IsFeatured = true },

            // English
            new() { Id = 10, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develops academic writing skills through essay composition, argumentation, research methods, and critical reading. Students produce a portfolio of revised work.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Humanities 305", DepartmentId = 4, InstructorId = 5 },
