@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <select name="dept" class="form-select">
            <option value="">All Departments</option>
            @foreach (var d in Catalog.GetDepartments())
            {
                if (d.Id == DepartmentFilter)
                {
                    <option value="@d.Id" selected>@d.Name</option>
                }
                else
                {
                    <option value="@d.Id">@d.Name</option>
                }
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var results = Catalog.SearchCourses(Search, DepartmentFilter);
}

<p class="text-muted">Showing @results.Count course(s)</p>

<table class="table table-striped table-hover">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Department</th>
            <th>Credits</th>
            <th>Schedule</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in results)
        {
            var dept = Catalog.GetDepartment(course.DepartmentId);
            <tr>
                <td>@course.Code</td>
                <td>@course.Title</td>
                <td>@dept?.Name</td>
                <td>@course.Credits</td>
                <td>@course.Schedule</td>
                <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try broadening your search.</div>
}

@code {
    [SupplyParameterFromQuery(Name = "search")]
    public string? Search { get; set; }

    [SupplyParameterFromQuery(Name = "dept")]
    public int? DepartmentFilter { get; set; }
}

