@page "/departments"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Departments</PageTitle>

<h1>Academic Departments</h1>
<p class="lead">Select a department to browse its course offerings.</p>

<div class="row">
    @foreach (var dept in Catalog.GetDepartments())
    {
        var courseCount = Catalog.GetCoursesByDepartment(dept.Id).Count;
        <div class="col-lg-4 col-md-6 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@dept.Code · @courseCount course(s)</h6>
                    <p class="card-text">@dept.Description</p>
                </div>
                <div class="card-footer">
                    <a href="departments/@dept.Id" class="btn btn-primary btn-sm">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@page "/departments/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

@{
    var dept = Catalog.GetDepartment(Id);
}

@if (dept is null)
{
    <PageTitle>Department Not Found</PageTitle>
    <h1>Department Not Found</h1>
    <a href="departments" class="btn btn-primary">Back to Departments</a>
}
else
{
    var courses = Catalog.GetCoursesByDepartment(dept.Id);

    <PageTitle>@dept.Name</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="departments">Departments</a></li>
            <li class="breadcrumb-item active" aria-current="page">@dept.Name</li>
        </ol>
    </nav>

    <h1>@dept.Name (@dept.Code)</h1>
    <p class="lead">@dept.Description</p>

    <h3 class="mt-4">Courses</h3>

    @if (courses.Count == 0)
    {
        <div class="alert alert-info">No courses are currently listed for this department.</div>
    }
    else
    {
        <div class="row">
            @foreach (var course in courses)
            {
                var instructor = Catalog.GetInstructor(course.InstructorId);
                <div class="col-md-6 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.Code — @course.Title</h5>
                            <p class="card-text text-muted">@course.Credits credits · @instructor?.Name</p>
                            <p class="card-text">@course.Schedule — @course.Location</p>
                        </div>
                        <div class="card-footer">
                            <a href="courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                            <a href="enroll?courseId=@course.Id" class="btn btn-outline-success btn-sm">Enroll</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
