    public int Id { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill in the form below to request enrollment in a course. All fields marked with <strong>*</strong> are required.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@SubmittedCourseTitle</strong> has been received. You will be contacted at your university email with confirmation details.</p>
        <hr />
        <a href="enroll" class="btn btn-primary">Submit Another Request</a>
        <a href="courses" class="btn btn-outline-secondary ms-2">Browse Courses</a>
    </div>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="mt-4">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name *</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
            <ValidationMessage For="() => Model.StudentName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID *</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU123456" />
            <ValidationMessage For="() => Model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course *</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">— Select a course —</option>
                @foreach (var course in Catalog.GetAllCourses())
                {
                    <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="comments" class="form-label">Comments (optional)</label>
            <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
            <ValidationMessage For="() => Model.Comments" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private bool Submitted { get; set; }
    private string SubmittedCourseTitle { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        SubmittedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
        Catalog.SubmitEnrollment(Model);
        Submitted = true;
    }
}

